-- DEV ONLY: sample data mirroring findJobs_frontend/src/lib/portal/data.js.
-- Load: docker exec -i jportal-postgres psql -U dbuser -d jportal < migrations/dev_seed/jobs.sql
BEGIN;
-- Taxonomy terms used by the sample jobs (verified).
UPDATE jobs j SET normalized_inr_amount = ROUND(j.salary_max * r.rate_to_inr, 2), salary_min_inr = ROUND(j.salary_min * r.rate_to_inr, 2) FROM exchange_rates r WHERE r.currency = j.currency AND j.is_visible;
COMMIT;
